+                    for (var inferenceResponse : inferenceResults.asList()) {
+                        var request = bulkShardRequest.items()[inferenceResponse.id];
+                        try {
+                            applyInferenceResponses(request, inferenceResponse);
+                        } catch (Exception exc) {
+                            request.abort(bulkShardRequest.index(), exc);
+                        }
+                    }
+                } finally {
+                    onCompletion.run();
+                }
+            };
