+    private static Set<String> capabilities() {
+        /*
+         * Add all of our cluster features without the leading "esql."
+         */
+        List<String> caps = new ArrayList<>();
+        for (NodeFeature feature : new EsqlFeatures().getFeatures()) {
+            caps.add(cap(feature));
