+                for (var entry : inferenceRequests.entrySet()) {
+                    executeShardBulkInferenceAsync(entry.getKey(), null, entry.getValue(), releaseOnFinish.acquire());
+                }
+            }
+        }
+
+        private void executeShardBulkInferenceAsync(
+            final String inferenceId,
