+                            }
+                        }
+                    } finally {
+                        onFinish();
+                    }
+                }
+
+                @Override
+                public void onFailure(Exception exc) {
+                    try {
+                        for (FieldInferenceRequest request : requests) {
+                            addInferenceResponseFailure(
+                                request.index,
+                                new ElasticsearchException(
