+        return TransportVersions.ML_INFERENCE_COHERE_RERANK;
+    }
+
+    @Override
+    public void writeTo(StreamOutput out) throws IOException {
+        out.writeOptionalBoolean(returnDocuments);
+    }
+
+    public Boolean returnDocuments() {
